import sys

def longest_brute(s):
    n = len(s)
    best = 0
    for i in range(n):
        bal = 0
        for j in range(i, n):
            bal += 1 if s[j] == '(' else -1
            if bal < 0:
                break
            if bal == 0 and j - i + 1 > best:
                best = j - i + 1
    return best

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip()
    print(longest_brute(s))

import sys

def longest_opt(s):
    n = len(s)
    dp = [0] * (n + 1)
    best = 0
    for i in range(2, n + 1):
        if s[i - 1] == ')':
            if s[i - 2] == '(':
                dp[i] = dp[i - 2] + 2
            else:
                prev = i - dp[i - 1] - 1
                if prev >= 1 and s[prev - 1] == '(':
                    dp[i] = dp[i - 1] + 2 + dp[prev - 1]
            if dp[i] > best:
                best = dp[i]
    return best

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip()
    print(longest_opt(s))

import sys

def longest_best(s):
    stack = [-1]
    best = 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            elif i - stack[-1] > best:
                best = i - stack[-1]
    return best

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip()
    print(longest_best(s))
